"""In-process engine LLM token accumulation for benchmarks."""

from __future__ import annotations

import threading
from contextlib import contextmanager
from contextvars import ContextVar, Token
from dataclasses import dataclass
from datetime import datetime, timezone
from typing import Any, Dict, Iterator, Optional

from rasa.shared.providers.llm.llm_response import LLMUsage
from rasa.shared.utils.constants import LANGFUSE_METADATA_SESSION_ID
from rasa.utils.feature_flags import FeatureFlag, is_enabled

engine_token_session_id: ContextVar[Optional[str]] = ContextVar(
    "engine_token_session_id", default=None
)


@dataclass
class _UsageTotals:
    prompt: int = 0
    completion: int = 0
    total: int = 0
    generations: int = 0


_lock = threading.Lock()
_store: Dict[str, _UsageTotals] = {}


def is_collection_enabled() -> bool:
    """Return whether hidden sim/eval collection is enabled."""
    return is_enabled(FeatureFlag.SIM_EVAL_EXTENDED)


@contextmanager
def bind_engine_token_session(session_id: str) -> Iterator[None]:
    """Bind the active conversation id for LiteLLM usage recording."""
    if not is_collection_enabled() or not session_id:
        yield
        return
    token: Token[Optional[str]] = engine_token_session_id.set(session_id)
    try:
        yield
    finally:
        engine_token_session_id.reset(token)


def _resolve_session_id(
    *, litellm_kwargs: Optional[Dict[str, Any]] = None
) -> Optional[str]:
    session = engine_token_session_id.get()
    if session:
        return session
    if not litellm_kwargs:
        return None
    metadata = litellm_kwargs.get("metadata") or {}
    if isinstance(metadata, dict):
        value = metadata.get(LANGFUSE_METADATA_SESSION_ID)
        if value:
            return str(value)
    return None


def _snapshot_payload(
    *,
    session_id: str,
    status: str,
    totals: Optional[_UsageTotals] = None,
) -> Dict[str, Any]:
    fetched_at = datetime.now(timezone.utc).isoformat()
    if totals is None:
        return {
            "status": status,
            "session_id": session_id,
            "prompt": 0,
            "completion": 0,
            "total": 0,
            "generations": 0,
            "fetched_at": fetched_at,
        }
    return {
        "status": status,
        "session_id": session_id,
        "prompt": totals.prompt,
        "completion": totals.completion,
        "total": totals.total,
        "generations": totals.generations,
        "fetched_at": fetched_at,
    }


def record_engine_token_usage(
    usage: LLMUsage,
    *,
    model: Optional[str] = None,
    litellm_kwargs: Optional[Dict[str, Any]] = None,
) -> None:
    """Accumulate provider-reported usage for the active conversation."""
    del model  # reserved for future per-model breakdowns
    if not is_collection_enabled():
        return
    if usage.prompt_tokens <= 0 and usage.completion_tokens <= 0:
        return
    session_id = _resolve_session_id(litellm_kwargs=litellm_kwargs)
    if not session_id:
        return
    prompt = usage.prompt_tokens
    completion = usage.completion_tokens
    total = usage.total_tokens
    with _lock:
        totals = _store.setdefault(session_id, _UsageTotals())
        totals.prompt += prompt
        totals.completion += completion
        totals.total += total
        totals.generations += 1


def get_engine_token_usage(session_id: str) -> Dict[str, Any]:
    """Return accumulated usage for one conversation id."""
    if not is_collection_enabled():
        return _snapshot_payload(session_id=session_id, status="not_found")
    with _lock:
        totals = _store.get(session_id)
    if totals is None or totals.generations <= 0:
        return _snapshot_payload(session_id=session_id, status="not_found")
    return _snapshot_payload(session_id=session_id, status="complete", totals=totals)


def pop_engine_token_usage(session_id: str) -> None:
    """Drop accumulated usage when a conversation tracker is deleted."""
    if not is_collection_enabled():
        return
    with _lock:
        _store.pop(session_id, None)


def clear_engine_token_store() -> None:
    """Clear the in-memory store. Intended for tests."""
    with _lock:
        _store.clear()
